import { test, expect } from '@playwright/test';

test('waits for slow data without sleeping', async ({ page }) => {
  await page.goto('/async');
  await page.getByRole('button', { name: 'Load orders' }).click();
  await expect(page.getByText('Loading orders…')).toBeVisible();
  const orders = page.getByRole('list', { name: 'Orders' }).getByRole('listitem');
  await expect(orders).toHaveCount(3);
  await expect(orders).toContainText(['A-1001', 'A-1002', 'A-1003']);
});

test('soft assertions and polling', async ({ page }) => {
  await page.goto('/products');
  await expect.soft(page.getByRole('status')).toHaveText('Showing 12 of 12 products');
  await expect.poll(async () => (await page.request.get('/api/products?category=Fruit')).json())
    .toMatchObject({ total: 4 });
});
